// TypeScript Version: 4.1

import dgebrd = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 6 );
	const D = new Float64Array( 2 );
	const E = new Float64Array( 1 );
	const TAUQ = new Float64Array( 2 );
	const TAUP = new Float64Array( 2 );
	const WORK = new Float64Array( 100 );

	dgebrd( 'column-major', 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 6 );
	const D = new Float64Array( 2 );
	const E = new Float64Array( 1 );
	const TAUQ = new Float64Array( 2 );
	const TAUP = new Float64Array( 2 );
	const WORK = new Float64Array( 100 );

	dgebrd( 5, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( true, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( false, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( null, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( void 0, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( [], 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( {}, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
	dgebrd( ( x: number ): number => x, 3, 2, A, 3, D, E, TAUQ, TAUP, WORK, 100 ); // $ExpectError
}

